package com.kotlinsurvivors.features.room.domain

/**
 * Geometry of the Level 0 room. Every number is in pixels of the 640x360 room image
 * (assets/sprites/room.png). Generated by gen_room.py together with that image, so
 * the collision boxes always match what is drawn. Do not edit by hand.
 */
object RoomLayout {

    const val WIDTH  = 640f
    const val HEIGHT = 360f

    /** Area the player's feet box may occupy (inside the walls). */
    val walkable = Box(x = 30f, y = 150f, w = 580f, h = 184f)

    /** Where the player starts: on the rug, feet position. */
    const val START_X = 320f
    const val START_Y = 258f

    /** Touching this area (the doormat in front of the door) leaves the room. */
    val door = Box(x = 300f, y = 322f, w = 40f, h = 14f)

    /** Furniture the player cannot walk through. */
    val furniture: List<Named> = listOf(
        Named("desk", Box(246f, 126f, 162f, 24f)),
        Named("desk_chair", Box(312f, 164f, 34f, 16f)),
        Named("pc_tower", Box(412f, 126f, 30f, 22f)),
        Named("wardrobe", Box(30f, 126f, 52f, 20f)),
        Named("bed", Box(30f, 176f, 64f, 50f)),
        Named("nightstand", Box(100f, 204f, 22f, 14f)),
        Named("backpack", Box(32f, 300f, 40f, 28f)),
        Named("table_left", Box(166f, 308f, 84f, 20f)),
        Named("armchair", Box(254f, 308f, 46f, 20f)),
        Named("bookshelf", Box(538f, 130f, 34f, 18f)),
        Named("fridge", Box(578f, 130f, 38f, 18f)),
        Named("extinguisher", Box(596f, 174f, 14f, 10f)),
        Named("trash_bin", Box(500f, 246f, 38f, 14f)),
        Named("table_right", Box(470f, 312f, 92f, 20f))
    )

    data class Box(val x: Float, val y: Float, val w: Float, val h: Float) {
        val right: Float get() = x + w
        val bottom: Float get() = y + h

        fun intersects(other: Box): Boolean =
            x < other.right && right > other.x && y < other.bottom && bottom > other.y
    }

    data class Named(val name: String, val box: Box)
}
